CREATE TEMP TABLE profile_seed (case_id text PRIMARY KEY, building_id uuid NOT NULL UNIQUE, building_slug text NOT NULL UNIQUE, concept_zh text NOT NULL, concept_zh_hant text, concept_en text, concept_ja text, keywords_zh text[] NOT NULL, keywords_zh_hant text[] NOT NULL, keywords_en text[] NOT NULL, keywords_ja text[] NOT NULL, plan_url text, section_url text, source_url text NOT NULL, publication_status text NOT NULL) ON COMMIT DROP;
INSERT INTO profile_seed VALUES
  ('CASE-041', '9a7ada39-c60a-5805-ae54-e5df5b10a780'::uuid, 'inujima-seirensho-art-museum', '旧铜精炼所遗构被保存并转化为艺术和环境体验，展示工业遗产再生的空间可能。', NULL, 'Inujima Seirensho Art Museum is a reference case for reading Design topic: 工业heritage, art, environmental education, Design topic: 离岛. It can inform thesis thinking about mixed programs, operation, and place-making.', '旧精錬所の遺構を、アートと環境体験の場へ転用した事例。産業遺産を壊さず、場所の記憶を新しい公共体験に変えている。', ARRAY['工业遗产', '艺术', '环境教育', '离岛', '再利用']::text[], '{}'::text[], ARRAY['Design topic: 工业heritage', 'art', 'environmental education', 'Design topic: 离岛', 'reuse']::text[], ARRAY['産業遺産', 'アート', '環境教育', '離島', '再利用']::text[], NULL, NULL, 'https://benesse-artsite.jp/en/art/seirensho.html', 'published'),
  ('CASE-045', '30aef487-cc52-5198-af18-59fee1add670'::uuid, 'teshima-art-museum', '低矮无柱壳体与水滴、风和场地植物共同形成艺术、自然和身体感知的空间。', NULL, 'Teshima Art Museum is a reference case for reading art museum, nature, Design topic: 离岛, Design topic: 身体体验. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Teshima Art Museum」は、美術館・自然・離島・身体体験の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['美术馆', '自然', '离岛', '身体体验', '环境']::text[], '{}'::text[], ARRAY['art museum', 'nature', 'Design topic: 离岛', 'Design topic: 身体体验', 'Design topic: 环境']::text[], ARRAY['美術館', '自然', '離島', '身体体験', '環境']::text[], NULL, NULL, 'https://benesse-artsite.jp/en/art/teshima-artmuseum.html', 'published'),
  ('CASE-047', '053fb9eb-e536-5a1a-a070-5e1d23a865e7'::uuid, 'towada-art-center', '分散盒子与街道结合，艺术设施成为地方城市街景再生和市民交流的核心。', NULL, 'Towada Art Center is a reference case for reading art museum, artneighborhood, localregeneration, Design topic: 步行. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Towada Art Center」は、美術館・アート街区・地域再生・歩行の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['美术馆', '艺术街区', '地方再生', '步行', '市民交流']::text[], '{}'::text[], ARRAY['art museum', 'artneighborhood', 'localregeneration', 'Design topic: 步行', 'citizenexchange']::text[], ARRAY['美術館', 'アート街区', '地域再生', '歩行', '市民交流']::text[], NULL, NULL, 'https://towadaartcenter.com/en/about/', 'published'),
  ('CASE-051', '2f162c1a-4861-564e-ab0b-1080eaec389d'::uuid, 'kadokawa-culture-museum', '巨石般的文化博物馆把出版、艺术、动漫、图书和活动组织成郊区文化目的地。', NULL, 'Kadokawa Culture Museum is a reference case for reading cultural complex, Design topic: 博物馆, Design topic: 出版, youthculture. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Kadokawa Culture Museum」は、文化複合・博物館・出版・若者文化の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['文化复合', '博物馆', '出版', '青年文化', '郊区']::text[], '{}'::text[], ARRAY['cultural complex', 'Design topic: 博物馆', 'Design topic: 出版', 'youthculture', 'Design topic: 郊区']::text[], ARRAY['文化複合', '博物館', '出版', '若者文化', '郊外']::text[], NULL, NULL, 'https://kkaa.co.jp/en/project/tokorozawa-sakura-town-kadokawa-culture-museum/', 'published'),
  ('CASE-052', '73f72808-e942-57e1-9e81-e7da0701323a'::uuid, 'hoki-museum', '弯曲悬挑画廊嵌入绿色环境，为写实绘画提供安静、连续且沉浸的观看空间。', NULL, 'Hoki Museum is a reference case for reading art museum, Design topic: 安静, nature, Design topic: 私人收藏. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Hoki Museum」は、美術館・静か・自然・個人コレクションの関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['美术馆', '安静', '自然', '私人收藏', '疗愈']::text[], '{}'::text[], ARRAY['art museum', 'Design topic: 安静', 'nature', 'Design topic: 私人收藏', 'Design topic: 疗愈']::text[], ARRAY['美術館', '静か', '自然', '個人コレクション', '癒やし']::text[], NULL, NULL, 'https://www.nikken.co.jp/en/projects/cultural/hoki_museum.html', 'published'),
  ('CASE-053', '745996bf-533b-56f3-a80b-4f0fc7b2d269'::uuid, 'oita-prefectural-art-museum', '开放立面和公共界面让美术馆成为城市会客厅，弱化传统美术馆的封闭感。', NULL, 'Oita Prefectural Art Museum is a reference case for reading art museum, Design topic: open界面, Design topic: citizen广场, localculture. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Oita Prefectural Art Museum」は、美術館・開いた接地面・市民広場・地域文化の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['美术馆', '开放界面', '市民广场', '地方文化', '活动']::text[], '{}'::text[], ARRAY['art museum', 'Design topic: open界面', 'Design topic: citizen广场', 'localculture', 'activity']::text[], ARRAY['美術館', '開いた接地面', '市民広場', '地域文化', '活動']::text[], NULL, NULL, 'https://shigerubanarchitects.com/works/oita-prefectural-art-museum/', 'published'),
  ('CASE-054', 'abb72157-0dbf-549c-a378-3fe8ae013bd9'::uuid, 'kyoto-city-kyocera-museum-of-art', '历史公共美术馆通过入口、广场和地下动线更新，在保留记忆的同时打开城市界面。', NULL, 'Kyoto City KYOCERA Museum of Art is a reference case for reading Design topic: history建筑, art museumrenewal, entry, Design topic: 广场. It can inform thesis thinking about mixed programs, operation, and place-making.', '歴史的建築の保存と美術館更新を重ね、入口、広場、展示動線を現代化した事例。文化記憶と公共性を比較できる。', ARRAY['历史建筑', '美术馆更新', '入口', '广场', '文化记忆']::text[], '{}'::text[], ARRAY['Design topic: history建筑', 'art museumrenewal', 'entry', 'Design topic: 广场', 'Design topic: culture记忆']::text[], ARRAY['歴史的建築', '美術館更新', '入口', '広場', '文化記憶']::text[], NULL, NULL, 'https://kyotocity-kyocera.museum/en/architecture', 'published'),
  ('CASE-055', 'bf88b372-42b0-532f-87bb-33077fa0b6da'::uuid, 'nagasaki-prefectural-art-museum', '跨越运河的美术馆把两块场地和水边景观连接起来，形成面向港口的文化公共空间。', NULL, 'Nagasaki Prefectural Art Museum is a reference case for reading waterfront, art museum, Design topic: 运河, Design topic: 港口. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Nagasaki Prefectural Art Museum」は、水辺・美術館・運河・港の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['水边', '美术馆', '运河', '港口', '景观']::text[], '{}'::text[], ARRAY['waterfront', 'art museum', 'Design topic: 运河', 'Design topic: 港口', 'Design topic: 景观']::text[], ARRAY['水辺', '美術館', '運河', '港', '景観']::text[], NULL, NULL, 'https://kkaa.co.jp/en/project/nagasaki-prefectural-art-museum/', 'published'),
  ('CASE-058', '22d7c427-87f9-5884-84f0-f6c88fc65bde'::uuid, 'sagawa-art-museum', '围绕人工水庭的低层美术馆被称为漂浮的美术馆，艺术、茶室和水景形成静谧体验。', NULL, 'Sagawa Art Museum is a reference case for reading art museum, Design topic: 水庭, Design topic: 茶室, nature. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Sagawa Art Museum」は、美術館・水庭・茶室・自然の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['美术馆', '水庭', '茶室', '自然', '安静']::text[], '{}'::text[], ARRAY['art museum', 'Design topic: 水庭', 'Design topic: 茶室', 'nature', 'Design topic: 安静']::text[], ARRAY['美術館', '水庭', '茶室', '自然', '静か']::text[], NULL, NULL, 'https://www.sagawa-artmuseum.or.jp/en/', 'published'),
  ('CASE-060', 'f0416e50-a744-5391-b680-5948f6636ae8'::uuid, 'fukuda-art-museum', '嵯峨岚山的美术馆强调未来百年的日本建筑标准，连接传统收藏、庭园和观光街区。', NULL, 'Fukuda Art Museum is a reference case for reading art museum, Design topic: 传统culture, tourism, Design topic: 庭园. It can inform thesis thinking about mixed programs, operation, and place-making.', '観光地の中で、美術館、庭園、伝統文化を落ち着いた滞在体験としてまとめた事例。来訪者利用と地域景観の距離感を読める。', ARRAY['美术馆', '传统文化', '观光', '庭园', '历史街区']::text[], '{}'::text[], ARRAY['art museum', 'Design topic: 传统culture', 'tourism', 'Design topic: 庭园', 'historyneighborhood']::text[], ARRAY['美術館', '伝統文化', '観光', '庭園', '歴史街区']::text[], NULL, NULL, 'https://fukuda-art-museum.jp/en/concept', 'published'),
  ('CASE-109', '65cca6df-9211-5abc-8979-b0d618b42207'::uuid, 'kunsthaus-graz', '历史街区の中に強い現代美術館を挿入し、都市の記憶と新しい文化を対比させる。', NULL, 'A contemporary art museum inserted into a historic urban fabric, contrasting memory and new cultural identity.', '歴史的街区に強い造形の現代美術館を挿入した事例。保存、更新、入口、都市景観の対比を考える参考になる。', ARRAY['美术馆', '历史街区', '城市更新', '入口', '文化地标']::text[], '{}'::text[], ARRAY['museum', 'historic district', 'urban renewal', 'entrance', 'cultural landmark']::text[], ARRAY['美術館', '歴史街区', '都市更新', '入口', '文化拠点']::text[], NULL, NULL, 'https://www.museum-joanneum.at/kunsthaus-graz', 'published'),
  ('CASE-118', '4a276826-cf33-57ac-80ea-ea7ea805f0ad'::uuid, 'maxxi-museum-of-xxi-century-arts', '流動的な展示動線で現代美術館を都市的な内部街路として構成した事例。展示と移動の関係を考えられる。', NULL, 'Reference case for MAXXI: useful for comparing public program, urban interface, operation, and spatial experience.', '流動的な展示動線で現代美術館を都市的な内部街路として構成した事例。展示と移動の関係を考えられる。', ARRAY['美術館', '展示動線', '内部街路', '現代文化', '都市性']::text[], '{}'::text[], ARRAY['美術館', '展示動線', '内部街路', '現代文化', '都市性']::text[], ARRAY['美術館', '展示動線', '内部街路', '現代文化', '都市性']::text[], NULL, NULL, 'https://www.zaha-hadid.com/architecture/maxxi/', 'published'),
  ('CASE-124', '436fc652-fae5-57e5-8907-47f2b496cc73'::uuid, 'moesgaard-museum', '斜面の屋根と展示を一体化し、博物館を景観と歩行体験に接続した事例。自然教育や地域記憶に応用できる。', NULL, 'Reference case for Moesgaard Museum: useful for comparing public program, urban interface, operation, and spatial experience.', '斜面の屋根と展示を一体化し、博物館を景観と歩行体験に接続した事例。自然教育や地域記憶に応用できる。', ARRAY['博物館', '景観', '屋根', '自然教育', '地域記憶']::text[], '{}'::text[], ARRAY['博物館', '景観', '屋根', '自然教育', '地域記憶']::text[], ARRAY['博物館', '景観', '屋根', '自然教育', '地域記憶']::text[], NULL, NULL, 'https://www.henninglarsen.com/projects/moesgaard', 'published'),
  ('CASE-132', '37417806-10db-5418-a401-cfddbee92dff'::uuid, 'zeitz-mocaa', '穀物サイロを現代美術館へ転用した事例。産業遺産、展示、観光、都市再生の関係を読める。', NULL, 'Reference case for Zeitz MOCAA: useful for comparing public program, urban interface, operation, and spatial experience.', '穀物サイロを現代美術館へ転用した事例。産業遺産、展示、観光、都市再生の関係を読める。', ARRAY['産業遺産', '美術館', 'サイロ', '再利用', '都市再生']::text[], '{}'::text[], ARRAY['産業遺産', '美術館', 'サイロ', '再利用', '都市再生']::text[], ARRAY['産業遺産', '美術館', 'サイロ', '再利用', '都市再生']::text[], NULL, NULL, 'https://heatherwick.com/projects/buildings/zeitz-mocaa/', 'published');

