  ('745996bf-533b-56f3-a80b-4f0fc7b2d269'::uuid, 'oita-prefectural-art-museum', 'museum', true, 1.000, 'https://shigerubanarchitects.com/works/oita-prefectural-art-museum/', 'Shigeru Ban Architects records the completed 2014 museum in Oita and describes its cedar-braced facade and flexible atrium.', '2026-07-12T00:00:00Z'::timestamptz),
  ('abb72157-0dbf-549c-a378-3fe8ae013bd9'::uuid, 'kyoto-city-kyocera-museum-of-art', 'museum', true, 1.000, 'https://kyotocity-kyocera.museum/en/architecture', 'The museum identifies Jun Aoki and Tezzo Nishizawa as master designers of the renewal and records the March 2020 reopening.', '2026-07-12T00:00:00Z'::timestamptz),
