  ('22d7c427-87f9-5884-84f0-f6c88fc65bde'::uuid, 'sagawa-art-museum', 'museum', true, 1.000, 'https://www.sagawa-artmuseum.or.jp/en/', 'Sagawa Art Museum records its March 22, 1998 opening in Moriyama, Shiga. The Japan Institute of Architects identifies Takenaka Corporation as designer of the main building and administration wing.', '2026-07-12T00:00:00Z'::timestamptz),
